Nginx como cache HTTP com coalescing e stale, protegendo uma API Node pública sem mudar código:

proxy_cache_path /var/cache/nginx/api levels=1:2 keys_zone=api:50m max_size=2g inactive=10m use_temp_path=off;

location /api/public/ {
  proxy_cache api;
  proxy_cache_key "$scheme$host$uri$is_args$args";
  proxy_cache_valid 200 15s;
  proxy_cache_valid 404 5s;                                   # negative caching
  proxy_cache_lock on;                                        # 1 miss vai à origem; os demais esperam
  proxy_cache_lock_timeout 3s;
  proxy_cache_use_stale error timeout updating http_500 http_502 http_503;   # serve velho se a origem falhar
  proxy_cache_background_update on;                           # stale-while-revalidate
  proxy_ignore_headers Set-Cookie;                            # cuidado: só porque /public não tem sessão
  add_header X-Cache-Status $upstream_cache_status;           # HIT/MISS/STALE/UPDATING para debug
  proxy_pass http://api;
}

Antes: 3.000 rps em /api/public/destaques chegando ao Node. Depois: ~0,07 rps na origem (1 a cada 15s), o resto HIT no Nginx; durante um deploy com falha da origem, STALE por 2 min e nenhum usuário percebeu.

ETag barato na API: res.set('ETag', `"${produto.versao}"`); if (req.get('If-None-Match') === etag) return res.status(304).end(); — poupa banda; a query ainda roda (para poupar CPU, cache de dados).

Compilação de templates de e-mail (Handlebars) — cara (~4ms) e pura por (templateId, versao):

const LRU = require('lru-cache');
const compilados = new LRU({ max: 500 });        // limite: 500 templates × ~50KB = 25MB máx

function getTemplate(id, versao) {
  const k = `${id}:${versao}`;                    // chave primitiva, não objeto
  let t = compilados.get(k);
  if (!t) { t = Handlebars.compile(fonte(id, versao)); compilados.set(k, t); }
  return t;
}

Leak real encontrado num heap snapshot: memoize de 'calcularFrete(pedido)' com chave JSON.stringify(pedido) — cada pedido é único, 0% de hit, 2GB de Map em 3 dias. Corrigido para chave (cep, pesoFaixa, transportadora) — 400 combinações, 98% de hit — e max: 5000.

Promise memoizada com rejeição:
const memoAsync = (fn) => { const m = new Map(); return (k) => {
  if (!m.has(k)) m.set(k, fn(k).catch(e => { m.delete(k); throw e; }));  // não cacheia erro
  return m.get(k); }; };

Em React: useMemo(() => ordenar(lista), [lista]) — vale se ordenar custa > o render; useMemo(() => a + b, [a, b]) custa mais que a soma.

SWR em cache de app com Redis:

async function getSWR(key, { fresh = 60, stale = 300 }, loader) {
  const raw = await redis.get(key);
  if (raw) {
    const { v, freshUntil } = JSON.parse(raw);
    if (Date.now() > freshUntil) {
      metrics.servedStale.inc();
      // refresh em background, sem await, com coalescing para ser 1 por processo
      coalesce(`swr:${key}`, () => refresh(key, fresh, stale, loader))
        .catch(e => log.warn({ err: e, key }, 'swr refresh falhou'));
    }
    return v;                                           // sempre latência de hit
  }
  return refresh(key, fresh, stale, loader);            // miss real: só quando nunca houve valor
}
async function refresh(key, fresh, stale, loader) {
  const v = await loader();
  await redis.set(key, JSON.stringify({ v, freshUntil: Date.now() + fresh * 1000 }), 'EX', fresh + stale);
  return v;
}

Medido em /home (1.200 rps, loader de 220ms): antes, p99 = 240ms a cada expiração; depois, p99 = 9ms sempre, 1 loader a cada ~60s por processo, e uma queda de 4 min do serviço de destaques passou sem nenhum 5xx (servindo stale de até 5 min).

HTTP equivalente na CDN: Cache-Control: public, s-maxage=60, stale-while-revalidate=300, stale-if-error=600.

Configuração do cliente para o Redis ser opcional de verdade:

const Redis = require('ioredis');
const redis = new Redis({
  host, port,
  connectTimeout: 1000,
  commandTimeout: 150,               // GET que não voltou em 150ms é miss
  maxRetriesPerRequest: 1,           // não fica tentando por request
  enableOfflineQueue: false,         // desconectado = erro imediato, não fila infinita
  retryStrategy: (n) => Math.min(n * 200, 5000),
  lazyConnect: false,
});
redis.on('error', (e) => metrics.redisErrors.inc());   // sem handler, 'error' não tratado mata o processo

// wrapper: cache é opcional
const cache = {
  async get(k) { try { return await redis.get(k); } catch { return null; } },
  async set(k, v, ttl) { try { await redis.set(k, v, 'EX', ttl); } catch {} },
};
// rate limit: decisão explícita de fail-open com log
async function rateLimitOk(id) {
  try { return (await redis.incr(`rl:${id}`)) <= 100; }
  catch { log.warn('rate limit fail-open: redis indisponível'); return true; }
}

Teste de caos em staging (k6 a 1.000 rps): docker stop redis.
- antes das mudanças: 100% das requests travadas por 30s+, Node com 10k sockets abertos, depois OOM. Redis derrubou tudo.
- depois: p99 de 8ms -> 60ms (agora vai ao PG), PG de 15% -> 70% CPU (aguenta, mas apertado — próxima ação: Sentinel com réplica), 0 erros. Sessões: usuários deslogados (aceito e documentado).

Infra: Sentinel com 1 réplica -> failover em ~15s, cache volta QUENTE. Warming só como plano B.
